import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { ContextPruningTracker } from "./src/core/context-pruning/tracker.ts";
import { DedupStrategy } from "./src/core/context-pruning/dedup.ts";
import { recoverablePrune } from "./src/core/context-pruning/recovery.ts";

const root = mkdtempSync(join(import.meta.dir, ".regression-"));
afterAll(() => rmSync(root, { recursive: true, force: true }));
const output = "結果 😀\\n".repeat(1000);
const args = { query: "example" };
const run = (tracker: ContextPruningTracker, id: string, scope = "session") =>
  tracker.process(id, "code_search", args, output, recoverablePrune(root, scope, id, output));

test("emitted shortened output and Unicode byte statistics survive reload", () => {
  const tracker = new ContextPruningTracker(root);
  const first = run(tracker, "full");
  const second = run(tracker, "short");
  const record = tracker.getHistory()[1];
  expect(record.originalOutput).toBe(output);
  expect(record.prunedOutput).toBe(second.output);
  expect(readFileSync(second.recoveryPath!, "utf8")).toBe(output);
  expect(second.bytesSaved).toBe(Buffer.byteLength(output) - Buffer.byteLength(second.output));
  expect(tracker.getStats()).toEqual({
    totalCalls: 2, prunedCalls: 1, totalBytesSaved: second.bytesSaved,
    estimatedContextBytes: Buffer.byteLength(first.output) + Buffer.byteLength(second.output),
  });
  const loaded = new ContextPruningTracker(root);
  loaded.loadHistory(JSON.parse(JSON.stringify(tracker.getHistory())));
  expect(loaded.getStats()).toEqual(tracker.getStats());
  expect(run(loaded, "third").output).toContain("callId: full");
});

test("evicted full result is replaced by a new full baseline", () => {
  const tracker = new ContextPruningTracker(root, 2);
  run(tracker, "old-full");
  run(tracker, "short-1");
  run(tracker, "short-2");
  const loaded = new ContextPruningTracker(root, 2);
  loaded.loadHistory(tracker.getHistory());
  expect(run(loaded, "new-full").modified).toBe(false);
  expect(run(loaded, "short-3").output).toContain("callId: new-full");
});

test("rejected recovery becomes the newest full-output baseline", () => {
  const tracker = new ContextPruningTracker(root);
  run(tracker, "first");
  run(tracker, "short");
  const rejected = run(tracker, "rejected", "");
  expect(rejected).toEqual({ output, modified: false, bytesSaved: 0 });
  expect(tracker.getHistory()[2].prunedOutput).toBeNull();
  expect(tracker.getStats().prunedCalls).toBe(1);
  expect(run(tracker, "next").output).toContain("callId: rejected");
  const loaded = new ContextPruningTracker(root);
  loaded.loadHistory(tracker.getHistory());
  expect(loaded.getStats()).toEqual(tracker.getStats());
});

test("recovery rejects larger replacements and retention failures", () => {
  const short = new ContextPruningTracker(root);
  short.process("a", "code_search", args, "tiny");
  expect(short.process("b", "code_search", args, "tiny", recoverablePrune(root, "session", "b", "tiny")))
    .toEqual({ output: "tiny", modified: false, bytesSaved: 0 });
  expect(short.getStats()).toEqual({ totalCalls: 2, prunedCalls: 0, totalBytesSaved: 0, estimatedContextBytes: 8 });
  const blocked = join(root, "not-a-directory");
  writeFileSync(blocked, "file");
  const tracker = new ContextPruningTracker(root);
  run(tracker, "base");
  expect(tracker.process("failed", "code_search", args, output, recoverablePrune(blocked, "s", "failed", output)).modified).toBe(false);
  expect(tracker.getHistory()[1].prunedOutput).toBeNull();
  expect(run(tracker, "after-failure").output).toContain("callId: failed");
});

test("different arguments and output do not dedup; side effects stay intact", () => {
  const tracker = new ContextPruningTracker(root);
  run(tracker, "base");
  expect(tracker.process("args", "code_search", { query: "different" }, output).modified).toBe(false);
  expect(tracker.process("output", "code_search", args, output + "changed").modified).toBe(false);
  expect(run(tracker, "matching").output).toContain("callId: base");
  for (const tool of ["Bash", "Write", "Edit", "mcp__aide__memory_add"]) {
    tracker.process(tool + "1", tool, args, output);
    expect(tracker.process(tool + "2", tool, args, output).modified).toBe(false);
  }
});

